raw.css:
:root {
  --color-primary: #2d5a4e;
  --color-primary-dark: #1a3a31;
  --color-accent: #d4a574;
  --color-accent-light: #e8c9a8;
  --color-accent-on-dark: #f0d9c1;
  --color-neutral-light: #fafaf8;
  --color-neutral-dark: #2a2a28;
  --color-success: #5a8a6f;
  --color-error: #a84c4c;
  --spacing-unit: 1rem;
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-xxl: 3rem;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Verdana, sans-serif;
  --font-mono: "Courier New", monospace;
  --font-script: "Palatino Linotype", "Book Antiqua", serif;
  --transition: 0.3s ease;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--color-neutral-dark);
  background-color: var(--color-neutral-light);
  margin: 0;
  padding: 0;
  line-height: 1.6;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-script);
  font-weight: 400;
  font-variant: small-caps;
  letter-spacing: 0.25em;
  margin: var(--spacing-lg) 0 var(--spacing-md) 0;
  color: var(--color-primary-dark);
}

h1 {
  font-size: clamp(1.75rem, 5vw, 2.5rem);
  margin-top: 0;
}

h2 {
  font-size: clamp(1.5rem, 4vw, 2rem);
}

h3 {
  font-size: clamp(1.25rem, 3vw, 1.5rem);
}

p {
  margin: var(--spacing-md) 0;
}

a {
  color: var(--color-primary-dark);
  text-decoration: none;
  transition: color var(--transition);
  position: relative;
}

a:hover {
  color: var(--color-accent);
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

header.site-header {
  background-color: white;
  border-bottom: 2px solid var(--color-primary);
  position: sticky;
  top: 0;
  z-index: 100;
}

header.site-header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-md);
  gap: var(--spacing-lg);
  flex-wrap: wrap;
}

.logo {
  font-family: var(--font-script);
  font-variant: small-caps;
  font-weight: 400;
  font-size: clamp(1.3rem, 4vw, 1.5rem);
  letter-spacing: 0.25em;
  color: var(--color-primary-dark);
  border-bottom: 1px solid var(--color-accent);
  padding-bottom: 0.25rem;
  white-space: nowrap;
  display: inline-block;
}

.logo:hover {
  color: var(--color-accent);
}

.logo:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

header nav {
  display: flex;
  gap: var(--spacing-lg);
  flex-wrap: wrap;
  align-items: center;
}

header nav a {
  font-weight: 500;
  padding: 0.5rem 0;
  border-bottom: 2px solid transparent;
  transition: border-color var(--transition), color var(--transition);
}

header nav a:hover {
  border-bottom-color: var(--color-accent);
}

header nav a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 4px;
}

footer.site-footer {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xxl) var(--spacing-md);
  margin-top: var(--spacing-xxl);
  text-align: center;
}

footer.site-footer a {
  color: var(--color-accent-on-dark);
  text-decoration: underline;
}

footer.site-footer a:hover {
  color: var(--color-accent-light);
}

footer.site-footer p {
  margin: var(--spacing-md) 0;
}

button, .btn, input[type="submit"], input[type="button"], input[type="reset"] {
  background-color: var(--color-primary-dark);
  color: white;
  border: none;
  padding: var(--spacing-md) var(--spacing-lg);
  min-height: 44px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color var(--transition), transform var(--transition);
  font-family: inherit;
}

button:hover, .btn:hover, input[type="submit"]:hover, input[type="button"]:hover, input[type="reset"]:hover {
  background-color: var(--color-accent);
  color: var(--color-neutral-dark);
}

button:focus, .btn:focus, input[type="submit"]:focus, input[type="button"]:focus, input[type="reset"]:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, .btn:active, input[type="submit"]:active, input[type="button"]:active, input[type="reset"]:active {
  transform: scale(0.98);
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: var(--spacing-sm);
  color: var(--color-primary-dark);
}

input[type="text"], input[type="email"], input[type="tel"], input[type="date"], textarea, select {
  width: 100%;
  padding: var(--spacing-md);
  min-height: 44px;
  font-size: 1rem;
  font-family: inherit;
  border: 2px solid var(--color-primary);
  border-radius: 4px;
  background-color: white;
  color: var(--color-neutral-dark);
  transition: border-color var(--transition);
}

input[type="text"]:focus, input[type="email"]:focus, input[type="tel"]:focus, input[type="date"]:focus, textarea:focus, select:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(212, 165, 116, 0.2);
}

textarea {
  resize: vertical;
  min-height: 120px;
  font-family: inherit;
}

.form-group {
  margin-bottom: var(--spacing-lg);
}

.card {
  background-color: white;
  border-radius: 8px;
  padding: var(--spacing-lg);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  transition: transform var(--transition), box-shadow var(--transition);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

.grid-2 {
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}

.grid-3 {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.btn-primary {
  background-color: var(--color-primary-dark);
  color: white;
}

.btn-primary:hover {
  background-color: var(--color-accent);
  color: var(--color-neutral-dark);
}

.btn-secondary {
  background-color: var(--color-accent);
  color: var(--color-neutral-dark);
}

.btn-secondary:hover {
  background-color: var(--color-primary-dark);
  color: white;
}

.text-center {
  text-align: center;
}

.text-muted {
  color: #666;
}

.mt-sm { margin-top: var(--spacing-sm); }
.mt-md { margin-top: var(--spacing-md); }
.mt-lg { margin-top: var(--spacing-lg); }
.mt-xl { margin-top: var(--spacing-xl); }
.mt-xxl { margin-top: var(--spacing-xxl); }

.mb-sm { margin-bottom: var(--spacing-sm); }
.mb-md { margin-bottom: var(--spacing-md); }
.mb-lg { margin-bottom: var(--spacing-lg); }
.mb-xl { margin-bottom: var(--spacing-xl); }
.mb-xxl { margin-bottom: var(--spacing-xxl); }

.section {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.section-alt {
  background-color: #f5f3f0;
}

@media (max-width: 600px) {
  header.site-header .container {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--spacing-md);
  }

  header nav {
    width: 100%;
    flex-direction: column;
    gap: var(--spacing-md);
    order: 3;
  }

  header nav a {
    display: block;
    width: 100%;
    padding: var(--spacing-md);
    border-bottom: 1px solid #e0e0e0;
  }

  .logo {
    font-size: clamp(1.1rem, 3vw, 1.3rem);
  }

  .container {
    padding: 0 var(--spacing-sm);
  }

  .section {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .grid, .grid-2, .grid-3 {
    grid-template-columns: 1fr;
  }

  h1 {
    font-size: 1.5rem;
  }

  h2 {
    font-size: 1.25rem;
  }

  button, .btn, input[type="submit"], input[type="button"], input[type="reset"] {
    width: 100%;
  }

  input[type="text"], input[type="email"], input[type="tel"], input[type="date"], textarea, select {
    font-size: 16px;
  }
}

@media (min-width: 601px) {
  .container {
    padding: 0 var(--spacing-lg);
  }

  .section {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  header nav {
    gap: var(--spacing-xl);
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

pages.css:
.index-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xxl) var(--spacing-md);
  min-height: 500px;
}

.index-hero .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xxl);
  align-items: center;
}

.index-hero-content {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-lg);
}

.index-hero h1 {
  color: var(--color-accent-on-dark);
  margin-top: 0;
}

.index-hero-subtitle {
  font-size: 1.25rem;
  line-height: 1.5;
  margin: 0;
}

.index-hero .btn {
  align-self: flex-start;
  background-color: var(--color-accent);
  color: var(--color-neutral-dark);
  padding: var(--spacing-md) var(--spacing-lg);
}

.index-hero .btn:hover {
  background-color: var(--color-accent-light);
}

.index-hero-image {
  width: 100%;
  height: auto;
  border-radius: 8px;
  display: block;
}

.index-featured {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.index-featured h2 {
  text-align: center;
  margin-top: 0;
}

.index-featured-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-xl);
}

.index-class-card {
  display: flex;
  flex-direction: column;
}

.index-class-card h3 {
  margin-top: 0;
}

.index-level {
  display: inline-block;
  background-color: var(--color-accent-light);
  color: var(--color-neutral-dark);
  padding: var(--spacing-xs) var(--spacing-sm);
  border-radius: 4px;
  font-size: 0.875rem;
  font-weight: 600;
  margin: var(--spacing-md) 0;
}

.index-class-card .btn {
  margin-top: auto;
}

.index-values {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.index-values h2 {
  margin-top: 0;
}

.index-values-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: var(--spacing-xl);
  margin-top: var(--spacing-xl);
}

.index-value-item {
  text-align: center;
}

.index-value-icon {
  font-size: 3rem;
  display: block;
  margin-bottom: var(--spacing-md);
}

.index-value-item h3 {
  color: var(--color-primary-dark);
}

.index-cta {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xxl) var(--spacing-md);
  text-align: center;
}

.index-cta-content {
  max-width: 600px;
  margin: 0 auto;
}

.index-cta h2 {
  color: var(--color-accent-on-dark);
  margin-top: 0;
}

.index-cta p {
  font-size: 1.1rem;
  margin-bottom: var(--spacing-lg);
}

.index-cta-buttons {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
}

.index-cta .btn {
  min-width: 180px;
}

.index-testimonials {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.index-testimonials h2 {
  text-align: center;
  margin-top: 0;
}

.index-testimonials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-xl);
}

.index-testimonial-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  border-left: 4px solid var(--color-accent);
  padding-left: var(--spacing-lg);
}

.index-testimonial-text {
  font-style: italic;
  color: var(--color-neutral-dark);
  margin-top: 0;
  line-height: 1.8;
}

.index-testimonial-author {
  color: var(--color-primary-dark);
  font-weight: 600;
  margin-bottom: 0;
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-xl) var(--spacing-sm);
    min-height: auto;
  }

  .index-hero .container {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .index-hero h1 {
    font-size: 1.75rem;
  }

  .index-hero-subtitle {
    font-size: 1.1rem;
  }

  .index-featured {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .index-values {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .index-cta {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .index-cta-buttons {
    flex-direction: column;
  }

  .index-cta .btn {
    width: 100%;
  }

  .index-testimonials {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .index-hero .btn {
    align-self: stretch;
  }
}

@media (min-width: 601px) {
  .index-hero {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .index-featured {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .index-values {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .index-cta {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .index-testimonials {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }
}

.schedule-filters {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
  margin: var(--spacing-lg) 0;
}

.schedule-filter-btn {
  background-color: #e8e8e8;
  color: var(--color-neutral-dark);
  border: 2px solid transparent;
  padding: var(--spacing-sm) var(--spacing-lg);
  min-height: 44px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color var(--transition), border-color var(--transition), color var(--transition);
  font-family: inherit;
}

.schedule-filter-btn:hover {
  background-color: var(--color-accent-light);
  border-color: var(--color-accent);
}

.schedule-filter-btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.schedule-filter-active {
  background-color: var(--color-primary-dark);
  color: white;
  border-color: var(--color-primary-dark);
}

.schedule-grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  margin-top: var(--spacing-xl);
}

.schedule-day {
  background-color: white;
  border-left: 4px solid var(--color-primary-dark);
  border-radius: 4px;
  padding: var(--spacing-lg);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.schedule-day h3 {
  margin-top: 0;
  color: var(--color-primary-dark);
  padding-bottom: var(--spacing-md);
  border-bottom: 2px solid var(--color-accent-light);
}

.schedule-class {
  padding: var(--spacing-md) 0;
  border-bottom: 1px solid #e8e8e8;
  transition: opacity var(--transition);
}

.schedule-class:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.schedule-class.hidden {
  display: none;
}

.schedule-class-time {
  font-weight: 700;
  color: var(--color-primary-dark);
  font-size: 0.95rem;
}

.schedule-class-name {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--color-neutral-dark);
  margin: var(--spacing-sm) 0;
}

.schedule-class-instructor {
  font-size: 0.9rem;
  color: #666;
  font-style: italic;
}

.schedule-class-badge {
  display: inline-block;
  margin-top: var(--spacing-sm);
  padding: 0.25rem var(--spacing-sm);
  font-size: 0.8rem;
  font-weight: 700;
  border-radius: 3px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.schedule-class-beginner .schedule-class-badge {
  background-color: #c8e6c9;
  color: #2e7d32;
}

.schedule-class-intermediate .schedule-class-badge {
  background-color: #ffe0b2;
  color: #e65100;
}

.schedule-class-advanced .schedule-class-badge {
  background-color: #ffcccc;
  color: #c62828;
}

@media (max-width: 600px) {
  .schedule-filters {
    gap: var(--spacing-sm);
  }

  .schedule-filter-btn {
    padding: var(--spacing-sm) var(--spacing-md);
    font-size: 0.9rem;
    flex: 1;
    min-width: calc(50% - var(--spacing-sm));
  }

  .schedule-grid {
    grid-template-columns: 1fr;
  }

  .schedule-day {
    padding: var(--spacing-md);
  }
}

@media (min-width: 601px) and (max-width: 900px) {
  .schedule-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 901px) {
  .schedule-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.teachers-intro {
  font-size: 1.1rem;
  color: #555;
  max-width: 700px;
  margin: var(--spacing-lg) 0;
}

.teachers-grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
}

.teachers-card {
  text-align: center;
  display: flex;
  flex-direction: column;
}

.teachers-card-image {
  width: 100%;
  height: 280px;
  object-fit: cover;
  border-radius: 8px 8px 0 0;
  margin: -var(--spacing-lg) -var(--spacing-lg) var(--spacing-lg) -var(--spacing-lg);
}

.teachers-card-name {
  font-size: 1.5rem;
  margin: var(--spacing-md) 0 var(--spacing-sm) 0;
  color: var(--color-primary-dark);
}

.teachers-card-specialty {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--color-accent);
  margin: 0 0 var(--spacing-sm) 0;
}

.teachers-card-experience {
  font-size: 0.95rem;
  color: #666;
  font-style: italic;
  margin: 0 0 var(--spacing-md) 0;
}

.teachers-card-bio {
  flex-grow: 1;
  text-align: left;
  font-size: 0.95rem;
  line-height: 1.6;
  margin: var(--spacing-md) 0;
  color: #555;
}

.teachers-card-quals {
  text-align: left;
  font-size: 0.9rem;
  color: var(--color-primary-dark);
  border-top: 1px solid #e0e0e0;
  padding-top: var(--spacing-md);
  margin-top: auto;
}

.teachers-benefits {
  display: grid;
  gap: var(--spacing-xl);
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  margin-top: var(--spacing-xl);
}

.teachers-benefit-item {
  background-color: white;
  padding: var(--spacing-lg);
  border-left: 4px solid var(--color-accent);
  border-radius: 4px;
}

.teachers-benefit-item h3 {
  margin-top: 0;
  color: var(--color-primary-dark);
}

.teachers-benefit-item p {
  margin: var(--spacing-md) 0 0 0;
  color: #666;
}

@media (max-width: 600px) {
  .teachers-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .teachers-card-image {
    height: 240px;
  }

  .teachers-intro {
    font-size: 1rem;
  }

  .teachers-benefits {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }
}

@media (min-width: 601px) {
  .teachers-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .teachers-card:nth-child(6) {
    grid-column: span 1;
  }
}

.pricing-intro {
  padding: var(--spacing-xl) var(--spacing-md);
  text-align: center;
}

.pricing-intro p {
  font-size: 1.1rem;
  color: #666;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: var(--spacing-xl);
  margin-top: var(--spacing-xl);
}

.pricing-card {
  background-color: white;
  border: 2px solid #e0e0e0;
  border-radius: 8px;
  padding: var(--spacing-lg);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
  position: relative;
  display: flex;
  flex-direction: column;
}

.pricing-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.12);
  border-color: var(--color-accent);
}

.pricing-card h3 {
  font-size: 1.4rem;
  margin-top: 0;
  margin-bottom: var(--spacing-md);
  color: var(--color-primary-dark);
}

.pricing-card-standard,
.pricing-card-premium {
  border-color: var(--color-accent);
  border-width: 3px;
}

.pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background-color: var(--color-accent);
  color: var(--color-neutral-dark);
  padding: 0.4rem 0.8rem;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: 20px;
  letter-spacing: 0.05em;
}

.pricing-amount {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin: var(--spacing-md) 0 0 0;
  line-height: 1;
}

.pricing-period {
  font-size: 0.95rem;
  color: #999;
  margin: var(--spacing-sm) 0 var(--spacing-lg) 0;
}

.pricing-features {
  list-style: none;
  padding: 0;
  margin: 0 0 var(--spacing-lg) 0;
  flex-grow: 1;
}

.pricing-features li {
  padding: 0.5rem 0;
  border-bottom: 1px solid #f0f0f0;
  font-size: 0.95rem;
  color: #555;
  position: relative;
  padding-left: 1.5rem;
}

.pricing-features li:last-child {
  border-bottom: none;
}

.pricing-features li:before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--color-success);
  font-weight: bold;
}

.pricing-btn {
  width: 100%;
  margin-top: auto;
}

.add-ons-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-xl);
}

.add-on-item {
  background-color: white;
  padding: var(--spacing-lg);
  border-radius: 6px;
  border-left: 4px solid var(--color-accent);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
}

.add-on-item h3 {
  margin-top: 0;
  font-size: 1.1rem;
  color: var(--color-primary-dark);
}

.add-on-item .pricing-amount {
  font-size: 1.5rem;
  margin: var(--spacing-sm) 0;
}

.add-on-item p {
  margin: var(--spacing-sm) 0 0 0;
  font-size: 0.95rem;
  color: #666;
}

.pricing-faq {
  max-width: 700px;
  margin: var(--spacing-xl) auto;
}

.faq-item {
  margin-bottom: var(--spacing-lg);
  border: 1px solid #e0e0e0;
  border-radius: 6px;
  background-color: white;
  overflow: hidden;
}

.faq-item summary {
  cursor: pointer;
  padding: var(--spacing-md) var(--spacing-lg);
  font-weight: 600;
  color: var(--color-primary-dark);
  background-color: #fafaf8;
  transition: background-color var(--transition), color var(--transition);
  user-select: none;
}

.faq-item summary:hover {
  background-color: var(--color-accent-light);
  color: var(--color-neutral-dark);
}

.faq-item summary:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: -3px;
}

.faq-item details[open] summary {
  background-color: var(--color-accent-light);
  border-bottom: 1px solid #e0e0e0;
}

.faq-item p {
  padding: var(--spacing-lg);
  background-color: white;
  margin: 0;
  font-size: 0.95rem;
  line-height: 1.7;
  color: #555;
}

.pricing-cta {
  background-color: var(--color-primary);
  color: var(--color-accent-on-dark);
}

.pricing-cta h2 {
  color: var(--color-accent-on-dark);
  margin-top: 0;
}

.pricing-cta p {
  color: var(--color-accent-on-dark);
  font-size: 1.05rem;
}

@media (max-width: 600px) {
  .pricing-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .pricing-card {
    padding: var(--spacing-md);
  }

  .pricing-amount {
    font-size: 2rem;
  }

  .add-ons-grid {
    grid-template-columns: 1fr;
  }

  .pricing-faq {
    margin: var(--spacing-lg) 0;
  }

  .faq-item summary {
    padding: var(--spacing-md);
  }

  .faq-item p {
    padding: var(--spacing-md);
  }

  .pricing-cta .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .pricing-intro {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }
}

.contact-intro {
  padding: var(--spacing-xxl) var(--spacing-md);
  text-align: center;
  background-color: var(--color-neutral-light);
}

.contact-intro p {
  font-size: 1.1rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.contact-form-section {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.contact-form {
  max-width: 600px;
  margin: var(--spacing-lg) auto 0 auto;
}

.contact-details {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.contact-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
}

.contact-card {
  background-color: white;
  padding: var(--spacing-lg);
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  transition: transform var(--transition), box-shadow var(--transition);
}

.contact-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.contact-card h3 {
  margin-top: 0;
  color: var(--color-primary-dark);
}

.contact-address {
  font-style: normal;
  line-height: 1.8;
}

.contact-address a {
  display: inline-block;
  margin-top: var(--spacing-md);
  color: var(--color-primary-dark);
  text-decoration: underline;
  font-weight: 500;
}

.contact-address a:hover {
  color: var(--color-accent);
}

.contact-hours {
  padding: var(--spacing-xxl) var(--spacing-md);
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
}

.contact-hours h2 {
  color: var(--color-accent-on-dark);
  margin-top: 0;
}

.hours-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
}

.hours-column {
  padding: var(--spacing-lg);
  background-color: rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  border-left: 4px solid var(--color-accent);
}

.hours-column h3 {
  color: var(--color-accent-on-dark);
  margin-top: 0;
  margin-bottom: var(--spacing-md);
}

.hours-column p {
  margin: var(--spacing-sm) 0;
  line-height: 1.8;
}

.hours-column .text-muted {
  color: rgba(240, 217, 193, 0.8);
}

@media (min-width: 601px) {
  .contact-intro {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .contact-form-section {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .contact-details {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .contact-hours {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }
}

@media (max-width: 600px) {
  .contact-intro {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .contact-intro p {
    font-size: 1rem;
  }

  .contact-form-section {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .contact-form {
    max-width: 100%;
  }

  .contact-details {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .contact-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .contact-hours {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .hours-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }
}

final.css:
:root {
  --color-primary: #2d5a4e;
  --color-primary-dark: #1a3a31;
  --color-accent: #d4a574;
  --color-accent-light: #e8c9a8;
  --color-accent-on-dark: #f0d9c1;
  --color-neutral-light: #fafaf8;
  --color-neutral-dark: #2a2a28;
  --color-success: #5a8a6f;
  --color-error: #a84c4c;
  --spacing-unit: 1rem;
  --spacing-xs: 0.25rem;
  --spacing-sm: 0.5rem;
  --spacing-md: 1rem;
  --spacing-lg: 1.5rem;
  --spacing-xl: 2rem;
  --spacing-xxl: 3rem;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Verdana, sans-serif;
  --font-mono: "Courier New", monospace;
  --font-script: "Palatino Linotype", "Book Antiqua", serif;
  --transition: 0.3s ease;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--color-neutral-dark);
  background-color: var(--color-neutral-light);
  margin: 0;
  padding: 0;
  line-height: 1.6;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-script);
  font-weight: 400;
  font-variant: small-caps;
  letter-spacing: 0.25em;
  margin: var(--spacing-lg) 0 var(--spacing-md) 0;
  color: var(--color-primary-dark);
}

h1 {
  font-size: clamp(1.75rem, 5vw, 2.5rem);
  margin-top: 0;
}

h2 {
  font-size: clamp(1.5rem, 4vw, 2rem);
}

h3 {
  font-size: clamp(1.25rem, 3vw, 1.5rem);
}

p {
  margin: var(--spacing-md) 0;
}

a {
  color: var(--color-primary-dark);
  text-decoration: none;
  transition: color var(--transition);
  position: relative;
}

a:hover {
  color: var(--color-accent);
}

a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

header.site-header {
  background-color: white;
  border-bottom: 2px solid var(--color-primary);
  position: sticky;
  top: 0;
  z-index: 100;
}

header.site-header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-md);
  gap: var(--spacing-lg);
  flex-wrap: wrap;
}

.logo {
  font-family: var(--font-script);
  font-variant: small-caps;
  font-weight: 400;
  font-size: clamp(1.3rem, 4vw, 1.5rem);
  letter-spacing: 0.25em;
  color: var(--color-primary-dark);
  border-bottom: 1px solid var(--color-accent);
  padding-bottom: 0.25rem;
  white-space: nowrap;
  display: inline-block;
}

.logo:hover {
  color: var(--color-accent);
}

.logo:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

header nav {
  display: flex;
  gap: var(--spacing-lg);
  flex-wrap: wrap;
  align-items: center;
}

header nav a {
  font-weight: 500;
  padding: 0.5rem 0;
  border-bottom: 2px solid transparent;
  transition: border-color var(--transition), color var(--transition);
}

header nav a:hover {
  border-bottom-color: var(--color-accent);
}

header nav a:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 4px;
}

footer.site-footer {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xxl) var(--spacing-md);
  margin-top: var(--spacing-xxl);
  text-align: center;
}

footer.site-footer a {
  color: var(--color-accent-on-dark);
  text-decoration: underline;
}

footer.site-footer a:hover {
  color: var(--color-accent-light);
}

footer.site-footer p {
  margin: var(--spacing-md) 0;
}

button, .btn, input[type="submit"], input[type="button"], input[type="reset"] {
  background-color: var(--color-primary-dark);
  color: white;
  border: none;
  padding: var(--spacing-md) var(--spacing-lg);
  min-height: 44px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color var(--transition), transform var(--transition);
  font-family: inherit;
}

button:hover, .btn:hover, input[type="submit"]:hover, input[type="button"]:hover, input[type="reset"]:hover {
  background-color: var(--color-accent);
  color: var(--color-neutral-dark);
}

button:focus, .btn:focus, input[type="submit"]:focus, input[type="button"]:focus, input[type="reset"]:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, .btn:active, input[type="submit"]:active, input[type="button"]:active, input[type="reset"]:active {
  transform: scale(0.98);
}

label {
  display: block;
  font-weight: 600;
  margin-bottom: var(--spacing-sm);
  color: var(--color-primary-dark);
}

input[type="text"], input[type="email"], input[type="tel"], input[type="date"], textarea, select {
  width: 100%;
  padding: var(--spacing-md);
  min-height: 44px;
  font-size: 1rem;
  font-family: inherit;
  border: 2px solid var(--color-primary);
  border-radius: 4px;
  background-color: white;
  color: var(--color-neutral-dark);
  transition: border-color var(--transition);
}

input[type="text"]:focus, input[type="email"]:focus, input[type="tel"]:focus, input[type="date"]:focus, textarea:focus, select:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(212, 165, 116, 0.2);
}

textarea {
  resize: vertical;
  min-height: 120px;
  font-family: inherit;
}

.form-group {
  margin-bottom: var(--spacing-lg);
}

.card {
  background-color: white;
  border-radius: 8px;
  padding: var(--spacing-lg);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  transition: transform var(--transition), box-shadow var(--transition);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

.grid-2 {
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}

.grid-3 {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.btn-primary {
  background-color: var(--color-primary-dark);
  color: white;
}

.btn-primary:hover {
  background-color: var(--color-accent);
  color: var(--color-neutral-dark);
}

.btn-secondary {
  background-color: var(--color-accent);
  color: var(--color-neutral-dark);
}

.btn-secondary:hover {
  background-color: var(--color-primary-dark);
  color: white;
}

.text-center {
  text-align: center;
}

.text-muted {
  color: #666;
}

.mt-sm { margin-top: var(--spacing-sm); }
.mt-md { margin-top: var(--spacing-md); }
.mt-lg { margin-top: var(--spacing-lg); }
.mt-xl { margin-top: var(--spacing-xl); }
.mt-xxl { margin-top: var(--spacing-xxl); }

.mb-sm { margin-bottom: var(--spacing-sm); }
.mb-md { margin-bottom: var(--spacing-md); }
.mb-lg { margin-bottom: var(--spacing-lg); }
.mb-xl { margin-bottom: var(--spacing-xl); }
.mb-xxl { margin-bottom: var(--spacing-xxl); }

.section {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.section-alt {
  background-color: #f5f3f0;
}

@media (max-width: 600px) {
  header.site-header .container {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--spacing-md);
  }

  header nav {
    width: 100%;
    flex-direction: column;
    gap: var(--spacing-md);
    order: 3;
  }

  header nav a {
    display: block;
    width: 100%;
    padding: var(--spacing-md);
    border-bottom: 1px solid #e0e0e0;
  }

  .logo {
    font-size: clamp(1.1rem, 3vw, 1.3rem);
  }

  .container {
    padding: 0 var(--spacing-sm);
  }

  .section {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .grid, .grid-2, .grid-3 {
    grid-template-columns: 1fr;
  }

  h1 {
    font-size: 1.5rem;
  }

  h2 {
    font-size: 1.25rem;
  }

  button, .btn, input[type="submit"], input[type="button"], input[type="reset"] {
    width: 100%;
  }

  input[type="text"], input[type="email"], input[type="tel"], input[type="date"], textarea, select {
    font-size: 16px;
  }
}

@media (min-width: 601px) {
  .container {
    padding: 0 var(--spacing-lg);
  }

  .section {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  header nav {
    gap: var(--spacing-xl);
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

pages.css:
.index-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xxl) var(--spacing-md);
  min-height: 500px;
}

.index-hero .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-xxl);
  align-items: center;
}

.index-hero-content {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-lg);
}

.index-hero h1 {
  color: var(--color-accent-on-dark);
  margin-top: 0;
}

.index-hero-subtitle {
  font-size: 1.25rem;
  line-height: 1.5;
  margin: 0;
}

.index-hero .btn {
  align-self: flex-start;
  background-color: var(--color-accent);
  color: var(--color-neutral-dark);
  padding: var(--spacing-md) var(--spacing-lg);
}

.index-hero .btn:hover {
  background-color: var(--color-accent-light);
}

.index-hero-image {
  width: 100%;
  height: auto;
  border-radius: 8px;
  display: block;
}

.index-featured {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.index-featured h2 {
  text-align: center;
  margin-top: 0;
}

.index-featured-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-xl);
}

.index-class-card {
  display: flex;
  flex-direction: column;
}

.index-class-card h3 {
  margin-top: 0;
}

.index-level {
  display: inline-block;
  background-color: var(--color-accent-light);
  color: var(--color-neutral-dark);
  padding: var(--spacing-xs) var(--spacing-sm);
  border-radius: 4px;
  font-size: 0.875rem;
  font-weight: 600;
  margin: var(--spacing-md) 0;
}

.index-class-card .btn {
  margin-top: auto;
}

.index-values {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.index-values h2 {
  margin-top: 0;
}

.index-values-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: var(--spacing-xl);
  margin-top: var(--spacing-xl);
}

.index-value-item {
  text-align: center;
}

.index-value-icon {
  font-size: 3rem;
  display: block;
  margin-bottom: var(--spacing-md);
}

.index-value-item h3 {
  color: var(--color-primary-dark);
}

.index-cta {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-xxl) var(--spacing-md);
  text-align: center;
}

.index-cta-content {
  max-width: 600px;
  margin: 0 auto;
}

.index-cta h2 {
  color: var(--color-accent-on-dark);
  margin-top: 0;
}

.index-cta p {
  font-size: 1.1rem;
  margin-bottom: var(--spacing-lg);
}

.index-cta-buttons {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
}

.index-cta .btn {
  min-width: 180px;
}

.index-testimonials {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.index-testimonials h2 {
  text-align: center;
  margin-top: 0;
}

.index-testimonials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-xl);
}

.index-testimonial-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  border-left: 4px solid var(--color-accent);
  padding-left: var(--spacing-lg);
}

.index-testimonial-text {
  font-style: italic;
  color: var(--color-neutral-dark);
  margin-top: 0;
  line-height: 1.8;
}

.index-testimonial-author {
  color: var(--color-primary-dark);
  font-weight: 600;
  margin-bottom: 0;
}

@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-xl) var(--spacing-sm);
    min-height: auto;
  }

  .index-hero .container {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .index-hero h1 {
    font-size: 1.75rem;
  }

  .index-hero-subtitle {
    font-size: 1.1rem;
  }

  .index-featured {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .index-values {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .index-cta {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .index-cta-buttons {
    flex-direction: column;
  }

  .index-cta .btn {
    width: 100%;
  }

  .index-testimonials {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .index-hero .btn {
    align-self: stretch;
  }
}

@media (min-width: 601px) {
  .index-hero {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .index-featured {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .index-values {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .index-cta {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .index-testimonials {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }
}

.schedule-filters {
  display: flex;
  gap: var(--spacing-md);
  justify-content: center;
  flex-wrap: wrap;
  margin: var(--spacing-lg) 0;
}

.schedule-filter-btn {
  background-color: #e8e8e8;
  color: var(--color-neutral-dark);
  border: 2px solid transparent;
  padding: var(--spacing-sm) var(--spacing-lg);
  min-height: 44px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color var(--transition), border-color var(--transition), color var(--transition);
  font-family: inherit;
}

.schedule-filter-btn:hover {
  background-color: var(--color-accent-light);
  border-color: var(--color-accent);
}

.schedule-filter-btn:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.schedule-filter-active {
  background-color: var(--color-primary-dark);
  color: white;
  border-color: var(--color-primary-dark);
}

.schedule-grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  margin-top: var(--spacing-xl);
}

.schedule-day {
  background-color: white;
  border-left: 4px solid var(--color-primary-dark);
  border-radius: 4px;
  padding: var(--spacing-lg);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.schedule-day h3 {
  margin-top: 0;
  color: var(--color-primary-dark);
  padding-bottom: var(--spacing-md);
  border-bottom: 2px solid var(--color-accent-light);
}

.schedule-class {
  padding: var(--spacing-md) 0;
  border-bottom: 1px solid #e8e8e8;
  transition: opacity var(--transition);
}

.schedule-class:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.schedule-class.hidden {
  display: none;
}

.schedule-class-time {
  font-weight: 700;
  color: var(--color-primary-dark);
  font-size: 0.95rem;
}

.schedule-class-name {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--color-neutral-dark);
  margin: var(--spacing-sm) 0;
}

.schedule-class-instructor {
  font-size: 0.9rem;
  color: #666;
  font-style: italic;
}

.schedule-class-badge {
  display: inline-block;
  margin-top: var(--spacing-sm);
  padding: 0.25rem var(--spacing-sm);
  font-size: 0.8rem;
  font-weight: 700;
  border-radius: 3px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.schedule-class-beginner .schedule-class-badge {
  background-color: #eff8ef;
  color: #276a2b;
}

.schedule-class-intermediate .schedule-class-badge {
  background-color: #ffe0b2;
  color: #ae3d00;
}

.schedule-class-advanced .schedule-class-badge {
  background-color: #ffe6e6;
  color: #b12424;
}

@media (max-width: 600px) {
  .schedule-filters {
    gap: var(--spacing-sm);
  }

  .schedule-filter-btn {
    padding: var(--spacing-sm) var(--spacing-md);
    font-size: 0.9rem;
    flex: 1;
    min-width: calc(50% - var(--spacing-sm));
  }

  .schedule-grid {
    grid-template-columns: 1fr;
  }

  .schedule-day {
    padding: var(--spacing-md);
  }
}

@media (min-width: 601px) and (max-width: 900px) {
  .schedule-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 901px) {
  .schedule-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.teachers-intro {
  font-size: 1.1rem;
  color: #555;
  max-width: 700px;
  margin: var(--spacing-lg) 0;
}

.teachers-grid {
  display: grid;
  gap: var(--spacing-lg);
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
}

.teachers-card {
  text-align: center;
  display: flex;
  flex-direction: column;
}

.teachers-card-image {
  width: 100%;
  height: 280px;
  object-fit: cover;
  border-radius: 8px 8px 0 0;
  margin: -var(--spacing-lg) -var(--spacing-lg) var(--spacing-lg) -var(--spacing-lg);
}

.teachers-card-name {
  font-size: 1.5rem;
  margin: var(--spacing-md) 0 var(--spacing-sm) 0;
  color: var(--color-primary-dark);
}

.teachers-card-specialty {
  font-size: 1.1rem;
  font-weight: 600;
  color: #9d6831;
  margin: 0 0 var(--spacing-sm) 0;
}

.teachers-card-experience {
  font-size: 0.95rem;
  color: #666;
  font-style: italic;
  margin: 0 0 var(--spacing-md) 0;
}

.teachers-card-bio {
  flex-grow: 1;
  text-align: left;
  font-size: 0.95rem;
  line-height: 1.6;
  margin: var(--spacing-md) 0;
  color: #555;
}

.teachers-card-quals {
  text-align: left;
  font-size: 0.9rem;
  color: var(--color-primary-dark);
  border-top: 1px solid #e0e0e0;
  padding-top: var(--spacing-md);
  margin-top: auto;
}

.teachers-benefits {
  display: grid;
  gap: var(--spacing-xl);
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  margin-top: var(--spacing-xl);
}

.teachers-benefit-item {
  background-color: white;
  padding: var(--spacing-lg);
  border-left: 4px solid var(--color-accent);
  border-radius: 4px;
}

.teachers-benefit-item h3 {
  margin-top: 0;
  color: var(--color-primary-dark);
}

.teachers-benefit-item p {
  margin: var(--spacing-md) 0 0 0;
  color: #666;
}

@media (max-width: 600px) {
  .teachers-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .teachers-card-image {
    height: 240px;
  }

  .teachers-intro {
    font-size: 1rem;
  }

  .teachers-benefits {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }
}

@media (min-width: 601px) {
  .teachers-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .teachers-card:nth-child(6) {
    grid-column: span 1;
  }
}

.pricing-intro {
  padding: var(--spacing-xl) var(--spacing-md);
  text-align: center;
}

.pricing-intro p {
  font-size: 1.1rem;
  color: #666;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: var(--spacing-xl);
  margin-top: var(--spacing-xl);
}

.pricing-card {
  background-color: white;
  border: 2px solid #e0e0e0;
  border-radius: 8px;
  padding: var(--spacing-lg);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  transition: transform var(--transition), box-shadow var(--transition), border-color var(--transition);
  position: relative;
  display: flex;
  flex-direction: column;
}

.pricing-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.12);
  border-color: var(--color-accent);
}

.pricing-card h3 {
  font-size: 1.4rem;
  margin-top: 0;
  margin-bottom: var(--spacing-md);
  color: var(--color-primary-dark);
}

.pricing-card-standard,
.pricing-card-premium {
  border-color: var(--color-accent);
  border-width: 3px;
}

.pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background-color: var(--color-accent);
  color: var(--color-neutral-dark);
  padding: 0.4rem 0.8rem;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: 20px;
  letter-spacing: 0.05em;
}

.pricing-amount {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin: var(--spacing-md) 0 0 0;
  line-height: 1;
}

.pricing-period {
  font-size: 0.95rem;
  color: #737373;
  margin: var(--spacing-sm) 0 var(--spacing-lg) 0;
}

.pricing-features {
  list-style: none;
  padding: 0;
  margin: 0 0 var(--spacing-lg) 0;
  flex-grow: 1;
}

.pricing-features li {
  padding: 0.5rem 0;
  border-bottom: 1px solid #f0f0f0;
  font-size: 0.95rem;
  color: #555;
  position: relative;
  padding-left: 1.5rem;
}

.pricing-features li:last-child {
  border-bottom: none;
}

.pricing-features li:before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--color-success);
  font-weight: bold;
}

.pricing-btn {
  width: 100%;
  margin-top: auto;
}

.add-ons-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-xl);
}

.add-on-item {
  background-color: white;
  padding: var(--spacing-lg);
  border-radius: 6px;
  border-left: 4px solid var(--color-accent);
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
}

.add-on-item h3 {
  margin-top: 0;
  font-size: 1.1rem;
  color: var(--color-primary-dark);
}

.add-on-item .pricing-amount {
  font-size: 1.5rem;
  margin: var(--spacing-sm) 0;
}

.add-on-item p {
  margin: var(--spacing-sm) 0 0 0;
  font-size: 0.95rem;
  color: #666;
}

.pricing-faq {
  max-width: 700px;
  margin: var(--spacing-xl) auto;
}

.faq-item {
  margin-bottom: var(--spacing-lg);
  border: 1px solid #e0e0e0;
  border-radius: 6px;
  background-color: white;
  overflow: hidden;
}

.faq-item summary {
  cursor: pointer;
  padding: var(--spacing-md) var(--spacing-lg);
  font-weight: 600;
  color: var(--color-primary-dark);
  background-color: #fafaf8;
  transition: background-color var(--transition), color var(--transition);
  user-select: none;
}

.faq-item summary:hover {
  background-color: var(--color-accent-light);
  color: var(--color-neutral-dark);
}

.faq-item summary:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: -3px;
}

.faq-item details[open] summary {
  background-color: var(--color-accent-light);
  border-bottom: 1px solid #e0e0e0;
}

.faq-item p {
  padding: var(--spacing-lg);
  background-color: white;
  margin: 0;
  font-size: 0.95rem;
  line-height: 1.7;
  color: #555;
}

.pricing-cta {
  background-color: var(--color-primary);
  color: var(--color-accent-on-dark);
}

.pricing-cta h2 {
  color: var(--color-accent-on-dark);
  margin-top: 0;
}

.pricing-cta p {
  color: var(--color-accent-on-dark);
  font-size: 1.05rem;
}

@media (max-width: 600px) {
  .pricing-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .pricing-card {
    padding: var(--spacing-md);
  }

  .pricing-amount {
    font-size: 2rem;
  }

  .add-ons-grid {
    grid-template-columns: 1fr;
  }

  .pricing-faq {
    margin: var(--spacing-lg) 0;
  }

  .faq-item summary {
    padding: var(--spacing-md);
  }

  .faq-item p {
    padding: var(--spacing-md);
  }

  .pricing-cta .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .pricing-intro {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }
}

.contact-intro {
  padding: var(--spacing-xxl) var(--spacing-md);
  text-align: center;
  background-color: var(--color-neutral-light);
}

.contact-intro p {
  font-size: 1.1rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.contact-form-section {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.contact-form {
  max-width: 600px;
  margin: var(--spacing-lg) auto 0 auto;
}

.contact-details {
  padding: var(--spacing-xxl) var(--spacing-md);
}

.contact-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
}

.contact-card {
  background-color: white;
  padding: var(--spacing-lg);
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  transition: transform var(--transition), box-shadow var(--transition);
}

.contact-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
}

.contact-card h3 {
  margin-top: 0;
  color: var(--color-primary-dark);
}

.contact-address {
  font-style: normal;
  line-height: 1.8;
}

.contact-address a {
  display: inline-block;
  margin-top: var(--spacing-md);
  color: var(--color-primary-dark);
  text-decoration: underline;
  font-weight: 500;
}

.contact-address a:hover {
  color: var(--color-accent);
}

.contact-hours {
  padding: var(--spacing-xxl) var(--spacing-md);
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
}

.contact-hours h2 {
  color: var(--color-accent-on-dark);
  margin-top: 0;
}

.hours-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: var(--spacing-lg);
  margin-top: var(--spacing-lg);
}

.hours-column {
  padding: var(--spacing-lg);
  background-color: rgba(255, 255, 255, 0.08);
  border-radius: 8px;
  border-left: 4px solid var(--color-accent);
}

.hours-column h3 {
  color: var(--color-accent-on-dark);
  margin-top: 0;
  margin-bottom: var(--spacing-md);
}

.hours-column p {
  margin: var(--spacing-sm) 0;
  line-height: 1.8;
}

.hours-column .text-muted {
  color: rgba(240, 217, 193, 0.8);
}

@media (min-width: 601px) {
  .contact-intro {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .contact-form-section {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .contact-details {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }

  .contact-hours {
    padding: var(--spacing-xxl) var(--spacing-lg);
  }
}

@media (max-width: 600px) {
  .contact-intro {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .contact-intro p {
    font-size: 1rem;
  }

  .contact-form-section {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .contact-form {
    max-width: 100%;
  }

  .contact-details {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .contact-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }

  .contact-hours {
    padding: var(--spacing-xl) var(--spacing-sm);
  }

  .hours-grid {
    grid-template-columns: 1fr;
    gap: var(--spacing-md);
  }
}
